// Generated by AikenFlow. These builders expose the protocol topology as code.
import type { Address, AikenFlowLucid, Assets, DataValue, SpendingValidator, TxComplete, UTxO, LockedDatum } from "./types.js";
import { lockedDatumToData } from "./types.js";

export * from "./types.js";

function redeemerToData(name: string): DataValue {
  return { constructor: 0, fields: [name] };
}

function assetUnit(name: string): string {
  return name === "ada" ? "lovelace" : name;
}

function unresolvedAmount(expression: string): bigint {
  throw new Error(`AikenFlow could not resolve amount expression: ${expression}`);
}

export interface DepositParams {
  lucid: AikenFlowLucid;
  lockedAddress: Address;
  lockedDatum: LockedDatum;
  amount: bigint;
  ownerSigner: Address;
}

export async function deposit(params: DepositParams): Promise<TxComplete> {
  let tx = params.lucid.newTx();

  tx = tx.payToContract(params.lockedAddress, { inline: lockedDatumToData(params.lockedDatum) }, { [assetUnit("ada")]: params.amount } as Assets);
  tx = tx.addSigner(params.ownerSigner);

  return tx.complete();
}

export interface WithdrawParams {
  lucid: AikenFlowLucid;
  lockedUtxos: UTxO[];
  lockedValidator?: SpendingValidator;
  lockedDatum: LockedDatum;
  validFrom?: number | bigint;
}

export async function withdraw(params: WithdrawParams): Promise<TxComplete> {
  let tx = params.lucid.newTx();

  if (params.lockedValidator && tx.attachSpendingValidator) tx = tx.attachSpendingValidator(params.lockedValidator);
  tx = tx.collectFrom(params.lockedUtxos, redeemerToData("Withdraw"));
  tx = tx.addSigner(params.lockedDatum.owner);
  tx = tx.validFrom(params.validFrom ?? params.lockedDatum.deadline);

  return tx.complete();
}

export interface EmergencyCancelParams {
  lucid: AikenFlowLucid;
  lockedUtxos: UTxO[];
  lockedValidator?: SpendingValidator;
  lockedDatum: LockedDatum;
  validTo?: number | bigint;
}

export async function emergencyCancel(params: EmergencyCancelParams): Promise<TxComplete> {
  let tx = params.lucid.newTx();

  if (params.lockedValidator && tx.attachSpendingValidator) tx = tx.attachSpendingValidator(params.lockedValidator);
  tx = tx.collectFrom(params.lockedUtxos, redeemerToData("EmergencyCancel"));
  tx = tx.addSigner(params.lockedDatum.owner);
  tx = tx.validTo(params.validTo ?? params.lockedDatum.deadline);

  return tx.complete();
}
